  assign rhs_1_wd = reg_wdata[63:0];

  assign ctrl_next_we = addr_hit[18] & reg_we & !reg_error;
  assign ctrl_next_wd = reg_wdata[0];

  assign ctrl_mode384_we = addr_hit[18] & reg_we & !reg_error;
  assign ctrl_mode384_wd = reg_wdata[1];

  // Read data return
  always_comb begin
    reg_rdata_next = '0;
    unique case (1'b1)
      addr_hit[0]: begin
        reg_rdata_next[63:0] = lhs128_0_qs;
      end

      addr_hit[1]: begin
        reg_rdata_next[63:0] = lhs128_1_qs;
      end

      addr_hit[2]: begin
        reg_rdata_next[63:0] = lhs384_0_qs;
      end

      addr_hit[3]: begin
        reg_rdata_next[63:0] = lhs384_1_qs;
      end

      addr_hit[4]: begin
        reg_rdata_next[63:0] = lhs384_2_qs;
      end

      addr_hit[5]: begin
        reg_rdata_next[63:0] = lhs384_3_qs;
      end

      addr_hit[6]: begin
        reg_rdata_next[63:0] = lhs384_4_qs;
      end

      addr_hit[7]: begin
        reg_rdata_next[63:0] = lhs384_5_qs;
      end

      addr_hit[8]: begin
        reg_rdata_next[63:0] = rhs_0_qs;
      end

      addr_hit[9]: begin
        reg_rdata_next[63:0] = rhs_1_qs;
      end

      addr_hit[10]: begin
        reg_rdata_next[63:0] = res128_0_qs;
      end

      addr_hit[11]: begin
        reg_rdata_next[63:0] = res128_1_qs;
      end

      addr_hit[12]: begin
        reg_rdata_next[63:0] = res384_0_qs;
      end

      addr_hit[13]: begin
        reg_rdata_next[63:0] = res384_1_qs;
      end

      addr_hit[14]: begin
        reg_rdata_next[63:0] = res384_2_qs;
      end

      addr_hit[15]: begin
        reg_rdata_next[63:0] = res384_3_qs;
      end

      addr_hit[16]: begin
        reg_rdata_next[63:0] = res384_4_qs;
      end

      addr_hit[17]: begin
        reg_rdata_next[63:0] = res384_5_qs;
      end

      addr_hit[18]: begin
        reg_rdata_next[0] = ctrl_next_qs;
        reg_rdata_next[1] = ctrl_mode384_qs;
      end

      addr_hit[19]: begin
        reg_rdata_next[0] = status_ready_qs;
        reg_rdata_next[1] = status_valid_qs;
      end

      default: begin
        reg_rdata_next = '1;
      end
    endcase
  end

  // Unused signal tieoff

  // wdata / byte enable are not always fully used
  // add a blanket unused statement to handle lint waivers
  logic unused_wdata;
  logic unused_be;
  assign unused_wdata = ^reg_wdata;
  assign unused_be = ^reg_be;

  // Assertions for Register Interface
  `ASSERT(en2addrHit, (reg_we || reg_re) |-> $onehot0(addr_hit))

endmodule
